function parseCSV(csv: string): Booking[] {
  const lines = csv.split('\n');
  const bookings: Booking[] = [];
  let idCounter = 1;
  
  for (const line of lines) {
    // Skip empty lines, comments, and headers
    if (!line.trim() || line.trim().startsWith('#') || line.startsWith('date,')) {
      continue;
    }
    
    // Simple CSV parsing - split by comma
    const parts = line.split(',');
    if (parts.length < 9) continue;
    
    const [date, startTime, endTime, hallId, subject, faculty, batch, branch, type] = parts.map(p => p.trim());
    
    // Only add valid entries
    if (date && hallId && subject && date !== 'TBD') {
      bookings.push({
        id: `auto-${idCounter++}`,
        hallId: hallId as any,
        year: batch,
        branch: branch,
        courseName: subject,
        date: date,
        startTime: startTime,
        endTime: endTime,
        isExtraClass: false,
        facultyName: faculty,
        classType: type
      });
    }
  }
  
  return bookings;
}

// Generate the complete timetable
export const generatedTimetableBookings = parseCSV(rawCSVData);

